package example
import ("context";"testing";"time")
func TestEvalCaseChannelPartialCancel1(t *testing.T) {
ctx,cancel:=context.WithCancel(context.Background());defer cancel();ch:=make(chan int)
    done:=make(chan struct{n int;e error},1);go func(){n,e:=SumChannel(ctx,ch);done<-struct{n int;e error}{n,e}}()
    ch<-23;ch<--8;cancel();select{case got:=<-done:if got.n!=15||got.e!=context.Canceled{t.Fatal(got)};case <-time.After(time.Second):t.Fatal("cancel ignored")}
}

